class Solution {
public:
    int minIncrementForUnique(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int moves = 0;
        for (int i = 1; i < (int)nums.size(); ++i) {
            if (nums[i] <= nums[i - 1]) {
                int diff = nums[i - 1] + 1 - nums[i];
                moves += diff;
                nums[i] = nums[i - 1] + 1;
            }
        }
        return moves;
    }
};

class Solution {
    public int minIncrementForUnique(int[] nums) {
        Arrays.sort(nums);
        int moves = 0;
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] <= nums[i - 1]) {
                int diff = nums[i - 1] + 1 - nums[i];
                moves += diff;
                nums[i] = nums[i - 1] + 1;
            }
        }
        return moves;
    }
}

var minIncrementForUnique = function(nums) {
    nums.sort((a, b) => a - b);
    let moves = 0;
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] <= nums[i - 1]) {
            const diff = nums[i - 1] + 1 - nums[i];
            moves += diff;
            nums[i] = nums[i - 1] + 1;
        }
    }
    return moves;
};
